      display: flex;
      flex-direction: column;
      gap: 16px;
    }", "new_string": "    /* 三列网格：左列 = 分组侧栏（贴屏幕左边缘），中列 = 任务区（在屏幕正中间），
       右列 = 与左列等宽的留白，靠它把中列推到视口正中（两侧对称，而不是被侧栏挤偏）。 */
    .shell {
      width: 100%;
      display: grid;
      grid-template-columns: 190px minmax(0, 1fr) 190px;
      gap: 20px;
      align-items: start;
    }
    .main {
      grid-column: 2;
      width: 100%;
      /* 任务区在中间列里居中，最大行宽限制避免超宽屏文案拉得过长 */
      max-width: 880px;
      margin: 0 auto;
      min-width: 0;
      display: flex;
      flex-direction: column;
      gap: 16px;
